## 2. Data Cleaning (`pipeline/cleaning.py`)

```python
"""Utilities for cleaning raw string records."""

import re
from typing import Optional


def strip_whitespace(value: Optional[str]) -> Optional[str]:
    """Trim surrounding whitespace; pass None through unchanged."""
    if value is None:
        return None
    return value.strip()


def normalize_case(value: Optional[str], mode: str = "lower") -> Optional[str]:
    """Normalize string case. mode must be 'lower' or 'upper'."""
    if value is None:
        return None
    if mode not in ("lower", "upper"):
        raise ValueError(f"Unknown mode: {mode!r}")
    return value.lower() if mode == "lower" else value.upper()


_PHONE_RE = re.compile(r"[^\d+]")

def clean_phone(value: Optional[str]) -> Optional[str]:
    """Keep only digits and a single leading '+', if present."""
    if value is None:
        return None
    cleaned = _PHONE_RE.sub("", value)
    if cleaned.startswith("+"):
        return "+" + cleaned[1:].lstrip("+")
    return cleaned


def parse_age(value: Optional[str]) -> Optional[int]:
    """Parse an age string. Returns None for blanks or invalid input."""
    if value is None:
        return None
    value = value.strip()
    if not value:
        return None
    try:
        age = int(value)
    except ValueError:
        return None
    if age < 0 or age > 150:
        return None
    return age
```

### Tests (`tests/test_cleaning.py`)

```python
import pytest
from pipeline.cleaning import (
    strip_whitespace, normalize_case, clean_phone, parse_age,
)


class TestStripWhitespace:
    def test_trims_spaces(self):
        assert strip_whitespace("  hello  ") == "hello"

    def test_none_passthrough(self):
        assert strip_whitespace(None) is None

    def test_empty_string(self):
        assert strip_whitespace("") == ""


class TestNormalizeCase:
    def test_lower(self):
        assert normalize_case("HELLO") == "hello"

    def test_upper(self):
        assert normalize_case("hello", mode="upper") == "HELLO"

    def test_none(self):
        assert normalize_case(None) is None

    def test_invalid_mode_raises(self):
        with pytest.raises(ValueError):
            normalize_case("x", mode="camel")


class TestCleanPhone:
    def test_removes_dashes_and_spaces(self):
        assert clean_phone("555-123 4567") == "5551234567"

    def test_keeps_leading_plus(self):
        assert clean_phone("+1 (555) 123-4567") == "+15551234567"

    def test_strips_interior_plus(self):
        assert clean_phone("55+5") == "555"

    def test_none(self):
        assert clean_phone(None) is None


class TestParseAge:
    def test_valid(self):
        assert parse_age("42") == 42

    def test_surrounding_whitespace(self):
        assert parse_age("  30 ") == 30

    def test_blank_is_none(self):
        assert parse_age("") is None
        assert parse_age(None) is None

    def test_non_numeric_is_none(self):
        assert parse_age("abc") is None

    def test_out_of_range_is_none(self):
        assert parse_age("-5") is None
        assert parse_age("999") is None
```

